const activeId = ref<string | null>(null);

function toggleActive(id: string) {
  activeId.value = activeId.value === id ? null : id;
}

const trackRef = ref<HTMLElement | null>(null);
const marqueeEl = ref<HTMLElement | null>(null);
const distance = ref(0);
let resizeObserver: ResizeObserver | null = null;

useScrollReveal(marqueeEl);

function measure() {
  const track = trackRef.value;
  const parent = track?.parentElement;
  if (!track || !parent) return;
  distance.value = Math.max(0, track.scrollWidth - parent.clientWidth);
}

onMounted(() => {
  measure();
  resizeObserver = new ResizeObserver(() => measure());
  if (trackRef.value?.parentElement) resizeObserver.observe(trackRef.value.parentElement);
});

onUnmounted(() => {
  resizeObserver?.disconnect();
});
</script>

<template>
  <div ref="marqueeEl" class="tech-marquee w-full max-w-full overflow-hidden" :style="{ '--marquee-distance': `${distance}px` }">
    <div ref="trackRef" class="tech-marquee__track">
      <button
        v-for="tech in techs"
        :key="tech.id"
        type="button"
        class="tech-chip"
        :class="{ 'tech-chip--active': activeId === tech.id }"
        :style="{ '--tech-color': tech.color }"
        @click="toggleActive(tech.id)"
      >
        <span aria-hidden="true" class="tech-chip__icon">
          <svg :viewBox="tech.viewBox" xmlns="http://www.w3.org/2000/svg">
            <component :is="shape.tag" v-for="(shape, i) in tech.shapes" :key="i" v-bind="shape.attrs" />
          </svg>
        </span>
        <span class="tech-chip__label">{{ tech.name }}</span>
      </button>
    </div>
  </div>
</template>

<style scoped>
