  overflow: hidden;
  position: relative;
  width: 100%;
}

.tech-marquee__track {
  display: flex;
  width: max-content;
  gap: 1rem;
  padding: 0.5rem 0;
  animation: tech-scroll 16s ease-in-out infinite alternate;
}

.tech-marquee:hover .tech-marquee__track,
.tech-marquee:focus-within .tech-marquee__track {
  animation-play-state: paused;
}

@keyframes tech-scroll {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(calc(-1 * var(--marquee-distance)));
  }
}

@media (min-width: 768.02px) {
  .tech-marquee {
    display: flex;
    justify-content: center;
  }

  .tech-marquee__track {
    animation: none;
    transform: none;
    flex-wrap: wrap;
    justify-content: center;
    width: 100%;
    max-width: 50rem;
    margin-top: 1.8em
  }
}

.tech-chip {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 3.5rem;
  height: 3.5rem;
  border-radius: 1.25rem;
  border: 1px solid rgb(var(--border) / 1);
  background: rgb(var(--card) / 0.7);
  color: var(--tech-color);
  cursor: pointer;
  transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
}

@media (min-width: 640px) {
  .tech-chip {
    width: 4rem;
    height: 4rem;
  }
}

.tech-chip:hover,
.tech-chip:focus-visible,
.tech-chip--active {
  transform: translateY(-4px) scale(1.05);
  border-color: var(--tech-color);
  box-shadow: 0 12px 24px -10px var(--tech-color);
  outline: none;
}

.tech-chip__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1.75rem;
  height: 1.75rem;
}

.tech-chip__icon svg {
  width: 100%;
  height: 100%;
}

.tech-chip__label {
  position: absolute;
